    14	
    15	// Mobile frame: a fixed 390×844 device. The AppBar and action area stay put; main scrolls.
    16	// The action area is the sticky bottom of the frame: a screen puts its main action there
    17	// so it stays visible while the content scrolls. Nothing is shown when it's empty.
    18	// `overlay` is for things that sit above the content, like a Toast. It's placed at the
    19	// bottom of the content area, just above the action area, never over the actions.
    20	// `sheet` is for a modal BottomSheet: it covers the whole frame, actions included.
    21	//
    22	// Every screen gets the same arrival: the page title becomes `title`, and after a screen
    23	// change focus moves to the screen's <h1>, so a screen reader announces where you are.
    24	// The first screen on page load keeps the browser's own focus.
    25	let hasChangedScreen = false; // set by App's navigation, never during render
    26	
    27	function PhoneFrame({ title, appBar, actions = null, overlay = null, sheet = null, children }) {
    28	  const frameRef = useRef(null);
    29	
    30	  useEffect(() => {
    31	    document.title = title;
    32	    if (hasChangedScreen) frameRef.current?.querySelector("h1")?.focus();
    33	  }, [title]);
    34	
    35	  return (
    36	    <div
    37	      ref={frameRef}
    38	      className="relative w-[390px] h-[844px] shrink-0 flex flex-col bg-neutral-50 rounded-[28px] shadow-xl overflow-hidden border border-neutral-300"
    39	    >
    40	      {appBar}
