    42	      {/* The overlay sits at the bottom of the content area, so it never covers the actions. */}
    43	      <div className="relative flex-1 min-h-0 flex flex-col">
    44	        <main className="phone-scroll flex-1 min-h-0 overflow-y-auto p-4 space-y-4">{children}</main>
    45	        {overlay}
